/* This page is a shell. Every record, original file and 3D snapshot requires
 * fresh server authorization; an unguessable URL never grants access. */
(()=>{'use strict';const $=s=>document.querySelector(s),status=$('#estimate-private-status'),article=$('#estimate-private-record'),id=new URLSearchParams(location.search).get('id'),base=String(window.MIREstimateConfig?.apiBase||'').replace(/\/$/,'');let sdk=null,token='',record=null,urls=[];
if(/^[a-f0-9-]{36}$/i.test(id||''))$('#estimate-login').href='chantier.html?return=estimate&request='+encodeURIComponent(id)+(new URLSearchParams(location.search).get('recette')==='1'?'&recette=1':'');
function section(title){const s=document.createElement('section');s.className='estimate-record-section';const h=document.createElement('h2');h.textContent=title;s.append(h);article.append(s);return s;}
function text(parent,value){const p=document.createElement('p');p.textContent=String(value);parent.append(p);}
function rows(parent,items){const ul=document.createElement('ul');for(const item of items||[]){const li=document.createElement('li');li.textContent=typeof item==='string'?item:item.text||MIREstimatePresentation.item(item);ul.append(li);}parent.append(ul);}
async function api(path){const r=await fetch(base+'/'+encodeURIComponent(id)+path,{headers:{authorization:'Bearer '+token},cache:'no-store',credentials:'omit'});if(!r.ok){let data;try{data=await r.json();}catch{}throw Error(data?.message||(r.status===401?'Connectez-vous avec votre compte équipe MIR.':r.status===403?'Ce compte n’est pas autorisé à consulter cette demande.':'La fiche ne peut pas être chargée.'));}return r;}
async function load(){article.hidden=true;article.replaceChildren();for(const url of urls)URL.revokeObjectURL(url);urls=[];$('#estimate-private-retry').disabled=true;try{if(!id||!/^[a-f0-9-]{36}$/i.test(id))throw Error('Le lien de cette fiche est incomplet.');if(!base)throw Error('L’accès aux fiches privées n’est pas encore raccordé au service d’estimation.');const c=window.MIRPortalConfig;if(!c?.enabled||!window.MIRSupabase)throw Error('Ouvrez Mon compte pour vérifier votre accès équipe.');if(!sdk)sdk=window.MIRSupabase.createClient(c.supabaseUrl,c.publishableKey,{auth:{flowType:'pkce',detectSessionInUrl:false,storageKey:'mir_portal_auth_'+c.projectRef}});const session=await sdk.auth.getSession();token=session.data?.session?.access_token||'';if(!token)throw Error('Connectez-vous avec votre compte équipe MIR, puis revenez à cette fiche.');record=await (await api('')).json();const p=record.payload;status.textContent=record.requestNumber+' · '+(record.status==='received'?'Demande reçue':'Transmission à vérifier')+' · '+new Date(record.createdAt).toLocaleString('fr-CA');article.hidden=false;
text(section('Coordonnées et chantier'),['Provenance : '+({general:'Formulaire général',studio:'Studio 3D',cart:'Panier',bending:'Pliage'}[p.source]||p.source),p.contact.name,p.contact.email,p.contact.phone,[p.address.street,p.address.city,p.address.postalCode].filter(Boolean).join(', '),'Note : '+(p.note||'Aucune note')].filter(Boolean).join('\n'));
const files=section('PDF originaux et dossier');files.classList.add('estimate-record-files');for(const file of record.files){const b=document.createElement('button');b.type='button';b.textContent='Télécharger '+file.filename;b.onclick=async()=>{b.disabled=true;try{const blob=await(await api('/files/'+file.id)).blob(),a=document.createElement('a'),url=URL.createObjectURL(blob);urls.push(url);a.href=url;a.download=file.filename;a.click();}catch(e){status.textContent=e.message;}finally{b.disabled=false;}};files.append(b);}if(!record.files.length)text(files,'Aucun PDF joint.');
if(p.selection)for(const group of MIREstimatePresentation.groups(p))rows(section(group.title),group.rows);
if(p.studio){const studio=(await(await api('/studio')).json()).studio;rows(section('À estimer · Métré préliminaire à valider'),studio.estimate);rows(section('Aperçu seulement · exclu du chiffrage par défaut'),studio.previewOnly);const facades=section('Façades et ouvertures soumises'),grid=document.createElement('div');grid.className='estimate-facades';facades.append(grid);for(const f of studio.faces||[]){const figure=document.createElement('figure'),img=document.createElement('img'),caption=document.createElement('figcaption'),url=URL.createObjectURL(new Blob([f.svg],{type:'image/svg+xml'}));urls.push(url);img.src=url;img.alt='Vue soumise — '+f.name;caption.textContent=f.name+' · Métré préliminaire à valider';figure.append(img,caption);grid.append(figure);const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Ouvertures et choix — '+f.name;details.append(summary);rows(details,MIREstimatePresentation.choiceRows(f.choices));rows(details,(f.openings||[]).map(o=>[o.type==='door'?'Porte':'Ouverture',o.name||o.id,'Largeur : '+(o.width??'À confirmer'),'Hauteur : '+(o.height??'À confirmer'),'Position : '+(o.x??'À confirmer')+' / '+(o.y??'À confirmer'),'Unités du projet soumis · métré préliminaire à valider'].join(' · ')));facades.append(details);}
if(studio.render3D){const viewer=section('Version 3D soumise'),canvas=document.createElement('canvas');canvas.width=1200;canvas.height=840;canvas.className='estimate-private-canvas';canvas.setAttribute('aria-label','Version 3D figée lors de la demande');const label=document.createElement('label');label.className='estimate-private-rotation';label.textContent='Tourner autour du projet soumis';const rotate=document.createElement('input');rotate.type='range';rotate.min='0';rotate.max='359';rotate.value=String(studio.render3D.angle||28);label.append(rotate);viewer.append(canvas,label);let renderId=0;const render=async()=>{const n=++renderId;try{const result=await window.MIR3D.render(canvas,{...studio.render3D,angle:Number(rotate.value)});if(n===renderId&&!result.rendered)text(viewer,'Volume incomplet dans le projet soumis ; les façades restent consultables.');}catch{if(n===renderId)text(viewer,'Le volume n’a pas pu être affiché. Les données et les façades soumises sont conservées.');}};rotate.oninput=render;await render();}}
}catch(error){status.textContent=error.message;article.hidden=true;}finally{$('#estimate-private-retry').disabled=false;}}
$('#estimate-private-retry').onclick=load;void load();})();
